package dev.smpcristalix.pvpcombat;import dev.smpcristalix.pvpcombat.api.*;import dev.smpcristalix.pvpcombat.command.PvPCombatCommand;import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import dev.smpcristalix.pvpcombat.data.YamlDataStore;import dev.smpcristalix.pvpcombat.listener.*;import dev.smpcristalix.pvpcombat.service.*;import org.bukkit.*;import org.bukkit.plugin.*;import org.bukkit.plugin.java.JavaPlugin;/** Composition root: no gameplay logic lives in Main. */public final class PvPCombatPlugin extends JavaPlugin{public static NamespacedKey CROSSBOW_KEY,TROPHY_TOTEM_KEY;private PvPCombatSettings settings;private YamlDataStore store;private StatsService stats;private ShardService shards;private CombatService combat;private PearlService pearls;private AbilityService abilities;private DeathPenaltyService penalties;private RewardService rewards;private UpgradeService upgrades;private GuiService gui;private ScoreboardService scoreboard;private CombatListener combatListener;private MovementListener movementListener;private TotemListener totemListener;private DeathListener deathListener;public void onEnable(){saveDefaultConfig();CROSSBOW_KEY=new NamespacedKey(this,"crossbow_projectile");TROPHY_TOTEM_KEY=new NamespacedKey(this,"trophy_totem_owner");settings=new PvPCombatSettings(getConfig());store=new YamlDataStore(this);store.load();stats=new StatsService(store,settings);shards=new ShardService(this,settings);combat=new CombatService(settings);pearls=new PearlService(settings);abilities=new AbilityService(this,stats,settings);penalties=new DeathPenaltyService(stats,settings);rewards=new RewardService(store,shards,settings);upgrades=new UpgradeService(stats,shards,settings);gui=new GuiService(stats,shards);scoreboard=new ScoreboardService(combat,pearls,settings);registerListeners();var c=getCommand("pvpcombat");if(c!=null)c.setExecutor(new PvPCombatCommand(this,gui,shards,stats));Bukkit.getServicesManager().register(PvPCombatApi.class,new PvPCombatApiImpl(shards,combat,stats),this,ServicePriority.Normal);Bukkit.getOnlinePlayers().forEach(stats::apply);Bukkit.getScheduler().runTaskTimer(this,()->{combat.clearExpired();for(var p:Bukkit.getOnlinePlayers()){if(combat.inCombat(p))scoreboard.update(p);else scoreboard.clear(p);}},10L,10L);getLogger().info("PvPCombat 1.0.0 enabled for Paper 1.21.1");}private void registerListeners(){combatListener=new CombatListener(combat,pearls,stats,abilities,settings);movementListener=new MovementListener(combat,abilities,settings);totemListener=new TotemListener(combat,settings);deathListener=new DeathListener(combat,pearls,penalties,rewards,settings);var pm=Bukkit.getPluginManager();pm.registerEvents(combatListener,this);pm.registerEvents(new CrossbowListener(),this);pm.registerEvents(movementListener,this);pm.registerEvents(new ShardGuiListener(shards,gui,upgrades),this);pm.registerEvents(totemListener,this);pm.registerEvents(new MaceListener(),this);pm.registerEvents(deathListener,this);pm.registerEvents(new PlayerLifecycleListener(stats,combat,pearls),this);}public void reloadPluginConfiguration(){reloadConfig();settings=new PvPCombatSettings(getConfig());stats.reload(settings);shards.reload(settings);combat.reload(settings);pearls.reload(settings);abilities.reload(settings);penalties.reload(settings);rewards.reload(settings);upgrades.reload(settings);scoreboard.reload(settings);combatListener.reload(settings);movementListener.reload(settings);totemListener.reload(settings);deathListener.reload(settings);Bukkit.getOnlinePlayers().forEach(stats::apply);}public void onDisable(){if(store!=null)store.save();Bukkit.getServicesManager().unregisterAll(this);}}
